import { test, expect } from '@playwright/test';

test.describe('Tablet Layout - Two-Column Grid', () => {
  test.beforeEach(async ({ page }) => {
    // Set tablet viewport size (iPad dimensions)
    await page.setViewportSize({ width: 768, height: 1024 });
    await page.goto('http://localhost:3000');
  });

  test('should display two-column grid layout on tablet viewport', async ({ page }) => {
    // Get the main content container
    const mainContent = page.getByRole('main');

    // Verify main content is visible
    await expect(mainContent).toBeVisible();

    // Get all grid items/cards
    const gridItems = page.locator('[data-testid="grid-item"], .grid-item, article');

    // Verify grid items exist
    const itemCount = await gridItems.count();
    expect(itemCount).toBeGreaterThan(0);

    // Get the grid container
    const gridContainer = page.locator('[data-testid="grid-container"], .grid-container, [role="region"]').first();

    // Verify grid container has two-column layout
    const computedStyle = await gridContainer.evaluate((element) => {
      return window.getComputedStyle(element);
    });

    // Check for CSS Grid with 2 columns
    const gridTemplateColumns = computedStyle.gridTemplateColumns;
    const columnCount = gridTemplateColumns.split(' ').filter(col => col !== '').length;

    expect(columnCount).toBe(2);
  });

  test('should maintain two-column layout when content is scrolled', async ({ page }) => {
    // Get grid container
    const gridContainer = page.locator('[data-testid="grid-container"], .grid-container, [role="region"]').first();

    // Scroll down to load more content if lazy loading is present
    await page.evaluate(() => window.scrollBy(0, 500));

    // Wait for any lazy-loaded content
    await page.waitForTimeout(500);

    // Verify grid still has two columns after scroll
    const computedStyle = await gridContainer.evaluate((element) => {
      return window.getComputedStyle(element);
    });

    const gridTemplateColumns = computedStyle.gridTemplateColumns;
    const columnCount = gridTemplateColumns.split(' ').filter(col => col !== '').length;

    expect(columnCount).toBe(2);
  });

