    // Get grid items
    const gridItems = page.locator('[data-testid="grid-item"], .grid-item, article');

    // Get first two items to check spacing
    const firstItem = gridItems.first();
    const secondItem = gridItems.nth(1);

    // Verify both items are visible
    await expect(firstItem).toBeVisible();
    await expect(secondItem).toBeVisible();

    // Get bounding boxes
    const firstBox = await firstItem.boundingBox();
    const secondBox = await secondItem.boundingBox();

    // Verify items are positioned side by side (same Y coordinate approximately)
    if (firstBox && secondBox) {
      // Items in same row should have similar Y positions
      const yDifference = Math.abs(firstBox.y - secondBox.y);
      expect(yDifference).toBeLessThan(50); // Allow small difference for alignment

      // Items should have horizontal separation (different X positions)
      const xDifference = Math.abs(firstBox.x - secondBox.x);
      expect(xDifference).toBeGreaterThan(0);
    }
  });

  test('should display grid items with equal width in two-column layout', async ({ page }) => {
    // Get grid items
    const gridItems = page.locator('[data-testid="grid-item"], .grid-item, article');

    // Get first two items
    const firstItem = gridItems.first();
    const secondItem = gridItems.nth(1);

    // Get bounding boxes
    const firstBox = await firstItem.boundingBox();
    const secondBox = await secondItem.boundingBox();

    // Verify items have equal width
    if (firstBox && secondBox) {
      const widthDifference = Math.abs(firstBox.width - secondBox.width);
      // Allow 5% tolerance for rounding
      const tolerance = Math.max(firstBox.width, secondBox.width) * 0.05;
      expect(widthDifference).toBeLessThanOrEqual(tolerance);
    }
  });

