    // Verify grid is still visible in landscape
    await expect(gridContainer).toBeVisible();

    // Verify it maintains two-column layout or adjusts appropriately
    const computedStyle = await gridContainer.evaluate((element) => {
      return window.getComputedStyle(element);
    });

    const gridTemplateColumns = computedStyle.gridTemplateColumns;
    const columnCount = gridTemplateColumns.split(' ').filter(col => col !== '').length;

    // Should have at least 2 columns in landscape
    expect(columnCount).toBeGreaterThanOrEqual(2);

    await landscapePage.close();
  });
});
